export function modelAcceptsDirectAudio(
  provider: AiProviderConfig,
  model: string,
): boolean {
  const modalities = provider.modelModalities?.[model];
  if (modalities) {
    return (
      modalities.input.includes("audio") && modalities.output.includes("text")
